-- 155: Original BrillaPrep WASSCE BrillaPrep transitional Electronics beta content blueprint questions, part 5.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_155_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_155_guard;
INSERT INTO _migration_155_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_021' AND NOT (q.topic_id IS 'topic_was_electronics_b002_5' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which bipolar transistor terminal controls collector current through a much smaller current?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The base","B. The emitter","C. The collector","D. The gate"]' AND q.correct_answer IS 'A' AND q.explanation IS 'In normal active operation, a relatively small base current controls a larger collector current, enabling amplification or switching. Therefore the correct answer is A: The base.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_021' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_155_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_022' AND NOT (q.topic_id IS 'topic_was_electronics_b002_5' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A transistor has collector current 40 mA and base current 0.2 mA. What is its current gain?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 20","B. 200","C. 80","D. 800"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Common-emitter current gain is collector current divided by base current, so 40 divided by 0.2 equals 200. Therefore the correct answer is B: 200.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_022' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_155_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_023' AND NOT (q.topic_id IS 'topic_was_electronics_b002_5' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In which region is a bipolar transistor intended to operate as a closed switch?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Cut-off","B. The active region","C. Saturation","D. Reverse breakdown"]' AND q.correct_answer IS 'C' AND q.explanation IS 'In saturation both junctions are driven so collector-emitter voltage is low and the device approximates a closed electronic switch. Therefore the correct answer is C: Saturation.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_023' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_155_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_024' AND NOT (q.topic_id IS 'topic_was_electronics_b002_5' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What defines Class A amplifier operation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The device conducts for half of each input cycle","B. The device conducts for less than half a cycle","C. Two devices conduct on alternate half-cycles","D. The active device conducts for the full input cycle"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A Class A stage is biased within the active region so conduction continues through 360 degrees of the signal cycle. Therefore the correct answer is D: The active device conducts for the full input cycle.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_024' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_155_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_025' AND NOT (q.topic_id IS 'topic_was_electronics_b002_5' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is an emitter bypass capacitor used in a common-emitter amplifier?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Increase AC gain while retaining DC bias stabilisation","B. Reduce AC gain while leaving DC bias unchanged","C. Remove the emitter resistor from the DC bias path","D. Couple the collector signal directly to the base"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The capacitor provides a low-reactance AC path around the emitter resistor while the resistor continues to stabilise the DC operating point. Therefore the correct answer is A: Increase AC gain while retaining DC bias stabilisation.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_025' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
